import heapq

def windowModes(nums, k):
    freq = {}
    heap = []
    out = []
    for i, x in enumerate(nums):
        f = freq.get(x, 0) + 1
        freq[x] = f
        heapq.heappush(heap, (-f, x))
        if i >= k:
            y = nums[i - k]
            g = freq[y] - 1
            if g:
                freq[y] = g
                heapq.heappush(heap, (-g, y))
            else:
                del freq[y]
        if i >= k - 1:
            while freq.get(heap[0][1], 0) != -heap[0][0]:
                heapq.heappop(heap)
            out.append(heap[0][1])
    return out
